#!/usr/bin/env python3
"""Deterministic static site from frozen evidence. No score estimates or promotion inference."""
from html import escape as e
import json
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'docs'
REPO = 'https://github.com/sassnarep3-star/GEMSDOESASS1'


def load(path):
    return json.loads((ROOT / path).read_text())


def page(title, body, *, prefix='', active='summary'):
    links = [('summary', 'index.html', 'Overview'), ('executive', 'executive-summary.html', 'Executive summary'),
             ('research', 'research.html', 'Research & sources'), ('evidence', 'evidence.html', 'Evidence')]
    nav = ''.join(f'<a href="{prefix}{url}"' + (' aria-current="page"' if key == active else '') + f'>{text}</a>' for key, url, text in links)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="GEMS fault-detection research: nine-site comparison, strict submission gates and auditable negative results.">
<meta name="color-scheme" content="light"><title>{e(title)} · GEMS Fieldnotes</title><link rel="stylesheet" href="{prefix}assets/site.css"></head>
<body><a class="skip" href="#main">Skip to content</a><header><div class="nav"><a class="brand" href="{prefix}index.html"><span class="mark" aria-hidden="true"></span>GEMS / FIELDNOTES</a><nav aria-label="Main">{nav}</nav></div></header>
<main id="main">{body}</main><footer><span>Independent research workspace · not an organizer website</span><span>Evidence before submission. No competition uploads automated.</span><a href="{REPO}">View repository ↗</a></footer><script src="{prefix}assets/source-feed.js" defer></script></body></html>'''


def table(rows, prefix=''):
    body = ''
    for row in sorted(rows, key=lambda r: -r['historical_report']):
        aliases = ', '.join(row['same_predictions_other_focus_sites'])
        duplicate = f'Exact predictions also in {e(aliases)}.' if aliases else 'No exact counterpart in another focus site found in this snapshot.'
        body += f'''<tr><td class="sitecell"><a href="{prefix}sites/{row['site']}.html">{row['site']} ↗</a><br><span class="small">Prior result</span></td>
<td><span class="reported">{row['historical_report']:.4f}</span><br><span class="badge">UNVERIFIED REPORT</span></td>
<td><a class="file" href="{row['source_url']}">{e(row['file'])}</a><span class="small">Source review only · not a new download</span></td>
<td><span class="muted">Unavailable</span><br><span class="small">No calibrated leaderboard estimate</span></td>
<td><span class="bad">No — already a prior submission</span><br><span class="small">{duplicate}</span></td>
<td class="bad nowrap">Not approved</td></tr>'''
    return f'''<p class="small">On smaller screens, scroll the table sideways to review every column.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Nine-site historical comparison"><table><thead><tr><th scope="col">Site</th><th scope="col">Historical report</th><th scope="col">Exact file to review</th><th scope="col">Estimated score</th><th scope="col">Unique new submission?</th><th scope="col">Submit?</th></tr></thead><tbody>{body}</tbody></table></div>
<p class="table-note">These are the highest historical results per site listed in your prompt, not independently confirmed maxima. Reports are excluded from validated score classes. No ORGANIZER-CONFIRMED receipts are available. Different file hashes do not imply different predictions.</p>'''


def gate_banner(prefix=''):
    return f'''<aside class="status" aria-label="Submission decision"><span class="pill">Negative · stop required</span><h2>BGAC-1: no TIFF cleared. H-PBSC research TIFF is not for upload.</h2><p>BGAC-1 failed the literal registry novelty gate. H-PBSC is a format-valid research TIFF but failed holdout and overlaps the calibration lattice above the protocol limit. SWGB’s earlier promotion was withdrawn after the same lattice audit. <strong>No file is approved for submission.</strong></p>
<p class="small"><a href="{prefix}evidence.html#correction">Review the superseding release decision and evidence ↗</a></p>
<p class="small" style="margin-top:13px;margin-bottom:0">Automated decision. No visual inspection required.<br>Competition slots used: none.</p></aside>'''


def metric_strip(card):
    return f'''<div class="metrics"><div class="metric"><span class="label">Exploratory HOLDOUT-DTI</span><span class="value">{card['holdout_dti']:.4f}</span><p>95% CI {card['ci95'][0]:.4f}–{card['ci95'][1]:.4f}</p></div>
<div class="metric"><span class="label">Same-run control DTI</span><span class="value">0.0730</span><p>95% CI 0.0569–0.0892</p></div>
<div class="metric"><span class="label">Final dot overlap</span><span class="value">100%</span><p>Within 3 px of one registry raster</p></div>
<div class="metric"><span class="label">New approved downloads</span><span class="value">None</span><p>Stop, do not use a weekly slot</p></div></div>
<p class="small">Both DTI measurements: <code>{card['evaluator_version']}</code> · {card['withheld_positive_pixels']:,} withheld positive pixels · 1,999 physical-block bootstrap resamples. Not leaderboard estimates. First-pass execution was protocol-disqualified before placement; retain as exploratory negatives only.</p>'''


def main():
    OUT.mkdir(exist_ok=True)
    audit = load('evidence/nine_site_audit.json')
    card = load('evidence/run_card.json')
    if card['approved_for_submission'] or card['verdict'] != 'negative':
        raise ValueError('This frozen negative-release site must not misrepresent a different approval state.')
    holdout = load('evidence/holdout.json')
    sources = load('knowledge/sources.json')
    feed = load('knowledge/source_feed.json') if (ROOT / 'knowledge/source_feed.json').exists() else None
    rows = audit['rows']
    head = '''<p class="eyebrow">Research release / 27 October 2026</p><section class="hero"><div><h1>A clear decision.<br>Backed by evidence.</h1><p class="lead">Nine prior sites reviewed. One geological hypothesis tested. No unverified score promises—and no duplicate file presented as a new submission.</p><div class="actions"><a class="button" href="executive-summary.html">Read executive summary ↗</a><a class="button secondary" href="evidence/run_card.json">Open run card</a></div><p class="tagline">FAULT DETECTION · SPATIAL HOLDOUT · FAIL-CLOSED EXPORT</p></div>''' + gate_banner() + '</section>'
    correction = '''<div class="callout"><strong>Review correction, not a hidden exception.</strong> Pass 2 found that the first surface check omitted positive-support overlap and continued despite an unassessable prior. Both are fixed. The corrected pre-placement gate already rejects this exact surface; the recorded holdout is exploratory, not promotion-qualified. <a href="evidence.html#correction">Read the full disclosure →</a></div>'''
    mainbody = head + metric_strip(card) + correction + '''<section class="section"><div class="section-head"><div><p class="eyebrow">The decision path</p><h2>Format is necessary. It isn't enough.</h2><p>Scientific merit, uniqueness and an uploadable file are separate checks. A code merge is not a submission approval.</p></div></div><div class="grid3">
<article class="panel"><p class="kicker">01 / Scientific signal</p><h3>BGAC-1 did not improve</h3><p>Signed gravity–basement gradient opposition underperformed the strongest same-run feature ablation. AUC canaries did not flag a leak; that does not establish absence of leakage.</p></article>
<article class="panel"><p class="kicker">02 / Literal novelty</p><h3>A lattice blocks the lane</h3><p>An existing 5 px lattice is within 3 px of 99.87% of the footprint. It captures every final BGAC-1 dot under the overlap rule. No density exemption was applied.</p></article>
<article class="panel"><p class="kicker">03 / Release decision</p><h3>No file, no weekly slot</h3><p>The mandatory protocol says stop on duplication. The project does not fabricate a new TIFF, score, validator receipt or download link after a failed gate.</p></article></div></section>
<section class="section" id="historical"><div class="section-head"><div><p class="eyebrow">The nine-site portfolio</p><h2>Historical leaders, not new submissions.</h2><p>GEMSDOE32 has the highest report in the supplied list. Every file below is already historical; none satisfies the request for a genuinely new submission.</p></div></div>''' + table(rows) + '''</section><section class="section grid2"><article class="panel"><p class="kicker">What changed in H33-B2?</p><h2>Pruning, not new discoveries.</h2><p>The actual GEMSDOE32 raster is exactly the site-31 base with 2,545 dots removed within 2 pixels of known faults. It adds no dots. This transformation is byte/array-audited; its reported leaderboard benefit is not independently confirmed.</p><a href="executive-summary.html#mechanism">See the mechanism audit →</a></article><article class="panel"><p class="kicker">Next work</p><h2>Resolve blockers first.</h2><p>Clarify the literal novelty policy, obtain official provenance and receipts, establish a compatible holdout incumbent, and audit source coupling before another method. The remaining two experiment slots are not a license to ignore the duplicate-stop rule.</p><a href="research.html#next">Read next-session plan →</a></article></section>'''
    (OUT / 'index.html').write_text(page('Overview', mainbody))
    mechanism = audit['h33_mechanism_audit']
    execbody = '''<p class="eyebrow">Executive summary / decision record</p><section class="hero"><div><h1>Do not submit<br>this run.</h1><p class="lead">There is no defensible “best new file” to recommend. The current experiment is negative, historical reports are not organizer receipts, and uniqueness is more than a new filename.</p><div class="actions"><a class="button" href="evidence/run_card.json">Download JSON run card</a><a class="button secondary" href="#how-to">Submission instructions ↓</a></div></div>''' + gate_banner() + '</section>' + metric_strip(card) + correction + '''<section class="section"><p class="eyebrow">File / score / uniqueness / approval</p><h2>The answer for each priority site.</h2><p class="lead">The estimated leaderboard score is unavailable for every row. Review exact original files and evidence without rebranding a previous submission.</p>''' + table(rows) + '''</section><section class="section" id="mechanism"><p class="eyebrow">Mechanism audit</p><h2>Why might GEMSDOE32 have improved?</h2><div class="grid2"><article class="panel"><h3>What is actually verified</h3><p>The H33-B2 mask is exactly <code>site31_base &amp; (distance_to_catalogue &gt; 2)</code>. The base has 40,199 dots, the result 37,654: 2,545 removed, none added. Its file SHA256 matches the pinned public mirror.</p><a href="''' + mechanism['code_source'] + '''">Inspect original code ↗</a><p class="small">The arithmetic and mask identity are locally measured, not organizer scoring evidence.</p></article><article class="panel"><h3>What remains a hypothesis</h3><p>Removing predictions with little credit for hidden new faults could reduce weighted false-positive mass while retaining recall. But nearness to an existing fault does not make a dot automatically false: a new nearby splay could earn credit. The upstream prose overstates that point.</p><p>Without hidden truth or a submission-page receipt, the reported 0.2778 is not a verified causal result, and it does not calibrate a forecast for a new method.</p></article></div><div class="callout">Can we exceed the reported 0.2778? It is possible in principle, but this experiment supplies no evidence that it can. Conflicting user-provided highs of 0.3195 and 0.4413 are not treated as the current leaderboard. No live official ranking was retrieved.</div><p><a href="https://github.com/sassnarep3-star/GEMSDOESASS1/blob/main/knowledge/scientific_analysis.md">Full mathematical interpretation, confounders and authority boundaries ↗</a></p></section>
<section class="section" id="how-to"><p class="eyebrow">How to submit / future cleared releases only</p><h2>A short path, once every gate passes.</h2><div class="grid2"><article class="panel"><ol class="steps"><li><div><strong>Check the opening decision.</strong>Only use a release explicitly approved by the separate selector. This run is blocked: there is no TIFF download to submit.</div></li><li><div><strong>Download the exact cleared TIFF.</strong>Compare its SHA256 with the published validator receipt. Do not use JSON, a report, a renamed old prediction, or the example template.</div></li><li><div><strong>Confirm the official slot allowance.</strong>Use your authorized competition account, follow the current rules and weekly cap. This workspace neither verifies the live cap nor uploads files.</div></li><li><div><strong>Choose the TIFF on “New submission”.</strong>The supplied form accepts a single-band GeoTIFF or a ZIP containing exactly one GeoTIFF. Match official CRS, shape and geotransform. Copy the published unique name and note of at most 140 characters.</div></li><li><div><strong>Retain the organizer receipt.</strong>Record filename, SHA256, note, submission identifier and returned result. Only that evidence can establish an ORGANIZER-CONFIRMED score for those bytes.</div></li></ol></article>
<article class="panel"><h3>Prevent the [0,1] rejection</h3><p>The shared writer rejects NaN, infinity, sentinels, negative values and values above one. It requires one float32 band, the reference grid, zero outside the footprint and zero support on known faults. It reopens and validates the TIFF and a one-TIFF ZIP before exposing outputs.</p><p>It never silently clips or fills invalid predictions. The original portal error's cause is unknown; NaN, a nodata sentinel or out-of-range values are possibilities, not diagnosed facts.</p><p><strong>No validator receipt for a nonexistent file.</strong> This run's file-level validation is null because the novelty gate prohibited packaging.</p><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/">Official competition ↗</a><div class="callout">Project checks are automatic. Official login and a future authorized slot-selector decision are access/competition controls, not a human visual-inspection step.</div></article></div></section>'''
    (OUT / 'executive-summary.html').write_text(page('Executive summary', execbody, active='executive'))
    for row in rows:
        checks = row['local_format_checks']
        checklist = ''.join(f'<li><span>{e(key.replace("_", " "))}</span><span class="{"good" if value else "bad"}">{"PASS" if value else "NO"}</span></li>' for key, value in checks.items())
        aliases = ', '.join(row['same_predictions_other_focus_sites']) or 'No exact counterpart in another focus site in this snapshot.'
        body = f'''<p class="breadcrumbs"><a href="../index.html#historical">Nine-site portfolio</a> / {row['site']}</p><p class="eyebrow">Individual executive summary</p><section class="hero"><div><h1>{row['site']}<br>Historical review.</h1><p class="lead">Highest result for this site listed in the supplied prompt: <strong>{row['historical_report']:.4f}</strong>, an unverified user/owner report. No organizer receipt or calibrated score estimate is available.</p><span class="pill neutral">Prior artifact · not a unique new submission</span></div>{gate_banner('../')}</section>
<div class="grid2"><article class="panel"><p class="kicker">Exact historical artifact</p><h3>Original file, without renaming.</h3><p class="mono">{e(row['file'])}</p><dl><dt>Estimated leaderboard score</dt><dd>Unavailable</dd><dt>New unique submission?</dt><dd class="bad">No — previously published</dd><dt>Same predictions elsewhere</dt><dd>{e(aliases)}</dd><dt>Method description</dt><dd>{e(row['method_summary'])} Owner description; not proof of scientific mechanism.</dd><dt>Positive pixels</dt><dd>{row['positive_pixels']:,} · locally measured</dd><dt>File SHA256</dt><dd class="mono">{row['sha256']}</dd><dt>Prediction-value SHA256</dt><dd class="mono">{row['canonical_footprint_sha256']}</dd></dl><div class="actions"><a class="button secondary" href="{row['source_url']}">Review pinned source file ↗</a></div><p class="small" style="margin-top:12px">Historical source review only. This is not a recommendation to download and resubmit.</p></article>
<article class="panel"><p class="kicker">Automated byte and grid audit</p><ul class="evidence-list">{checklist}</ul><p class="small" style="margin-top:14px">These checks describe the exact historical file, not a new release. Some historical variants have NaN outside the footprint and fail this project's conservative all-finite export policy. Organizer acceptance is not inferred.</p><a href="../evidence/nine_site_audit.json">Full audit and exact aliases →</a></article></div>
<section class="section"><h2>Submission decision: not approved.</h2><p class="lead">No file from this historical comparison is a newly generated candidate. The new BGAC-1 lane failed. Do not choose a weekly slot based on this summary.</p><a href="../executive-summary.html#how-to">How a future cleared file would be submitted →</a><p class="small">This subpage belongs to GEMSDOESASS1. The separate {row['site']} website has not been edited.</p></section>'''
        dest = OUT / 'sites' / f"{row['site']}.html"
        dest.parent.mkdir(exist_ok=True)
        dest.write_text(page(row['site'], body, prefix='../', active='executive'))
    sourcehtml = ''.join(f'<article class="source"><a href="{e(s["url"])}">{e(s["authority"])} ↗</a><p><strong>{e(s["access"])}</strong></p><p>{e(" ".join(s.get("claims_supported", [])) or "No claims independently verified from this URL.")}</p></article>' for s in sources['sources'])
    researchbody = '''<p class="eyebrow">Research / hypotheses / source boundaries</p><h1>Geology first.<br>Claims kept in bounds.</h1><p class="lead">The contest target is unmapped fault traces. Structural predictions can guide geothermal exploration; they do not establish vents, temperatures or economic resources.</p><section class="section"><h2>One frozen lane. Four ranked ideas.</h2><p>Qualitative expected benefit and cost are judgments, not numerical score projections. New to this empty checkout is not proof of novelty across all prior science or GEMSDOE repositories.</p><div class="table-wrap"><table><thead><tr><th>Priority</th><th>Hypothesis / layers</th><th>Target signature</th><th>Non-fault mimic / status</th></tr></thead><tbody>
<tr><td>1 · moderate benefit, low cost</td><td>BGAC-1 / gravity, basement, detrended topography</td><td>Signed antiparallel gradient consistency at 2 and 5 px scales; weak surface expression.</td><td>Depositional basin edge; shared inversion inputs. Tested once, negative and protocol-disqualified.</td></tr>
<tr><td>2 · low–moderate benefit, moderate cost</td><td>Conductivity curvature flank asymmetry</td><td>Opposite-flank second derivatives rather than scalar conductivity.</td><td>Saline groundwater / clay boundaries. Deferred; source resolution needs verification.</td></tr>
<tr><td>3 · low benefit, moderate cost</td><td>Gravity-edge scale translation / gravity and basement</td><td>Movement of gradient ridges under smoothing, not same-pixel agreement.</td><td>Lithologic or survey boundaries. Not tested.</td></tr>
<tr><td>4 · low benefit, moderate cost</td><td>Radiometric compositional break / K, Th, U and TMI</td><td>Persistent log-ratio contrast with a magnetic-contact veto.</td><td>Weathering or agriculture. Not viable yet: official source/quantization not independently verified.</td></tr></tbody></table></div><p class="small">The prompt referenced a lane paragraph but supplied none. BGAC-1 was explicitly frozen before implementation. No second or third hypothesis was tried after the duplicate stop.</p><a href="''' + REPO + '''/blob/main/knowledge/hypotheses.md">Full preregistration and correction disclosure ↗</a></section>
<section class="section"><h2>What the available evidence can support.</h2><div class="grid2"><article class="panel"><h3>Official GitHub code inspected</h3><p>The reference repository describes geological fault detection with U-Net and Monte Carlo cross-validation, using asymmetric Tversky training loss. Its README supplies CPU-only environments. Those facts do not authenticate the current contest evaluation formula, the mirror's origin, or a live leaderboard result.</p></article><article class="panel"><h3>Public mirror bytes measured</h3><p>The 19-band feature stack, catalogue and template were restored and SHA-verified. The template has shape 3730 × 3292, EPSG:32611 and 100 m pixels. Band tags describe the source layers. Hash consistency is not organizer provenance or data-license verification.</p></article></div></section><section class="section"><p class="eyebrow">Claim / source ledger</p><h2>Read, measured, or not reachable.</h2><p>Network access is limited to GitHub and package hosts. We do not claim to have fetched the official competition pages, rules PDF, USGS, GDR, INGENIOUS or Dropbox here. Links are retained for review, not fabricated verification.</p><div class="panel">''' + sourcehtml + '''</div></section>
<section class="section" id="next"><p class="eyebrow">Next session / highest priority first</p><h2>Do not optimize around a failed gate.</h2><div class="panel"><ol><li>Resolve the lattice-overlap policy obstruction explicitly outside this stopped run; no silent exceptions.</li><li>Obtain official data/rules/metric verification and organizer receipts without requesting credentials in chat.</li><li>Establish a reproducible compatible incumbent on identical visible-only buffered folds.</li><li>Audit gravity–basement source coupling, deferred layer metadata and external data availability.</li><li>Extend novelty coverage beyond the nine public sites and resolve the invalid prior before any clearance claim.</li><li>Only then preregister a new experiment, validate it, and route a successful artifact to a separate slot selector.</li></ol><a href="''' + REPO + '''/blob/main/knowledge/NEXT_STEPS.md">Complete next-session plan ↗</a></div></section>'''
    (OUT / 'research.html').write_text(page('Research and sources', researchbody, active='research'))
    bars = ''.join(f'<div class="barrow"><span>{e(key)}</span><div class="track"><div class="bar {"candidate" if key == "BGAC-1" else ""}" style="width:{score["dti"] / .12 * 100:.1f}%"></div></div><strong>{score["dti"]:.4f}</strong></div>' for key, score in sorted(holdout['scores'].items(), key=lambda item: -item[1]['dti']))
    feedhtml = '<p class="small">No source refresh has been run.</p>'
    if feed:
        feedhtml = f'<p class="small">Static snapshot checked: {e(feed["checked_utc"])}. GitHub heads only—not a current competition leaderboard. Changed heads require a new registry audit; they never update the frozen experiment.</p><p class="small" id="feed-live-status" role="status">Current GitHub freshness will be checked automatically if browser access is available.</p><div class="table-wrap"><table class="feed-grid"><thead><tr><th>Source</th><th>Experiment pin</th><th>Current head</th><th>Advisory</th></tr></thead><tbody>'
        for r in feed['sources']:
            state = 'Unavailable' if r['status'] != 'checked' else 'Changed — audit required' if r['changed_since_experiment'] else 'Matches snapshot'
            feedhtml += f'<tr data-source-repo="{r["repo"]}" data-frozen-ref="{r["frozen_ref"]}"><td>{r["repo"]}</td><td><code>{r["frozen_ref"][:12]}</code></td><td><code data-current-head>{(r.get("current_ref") or "unavailable")[:12]}</code></td><td data-advisory>{state}</td></tr>'
        feedhtml += '</tbody></table></div>'
    evidencebody = '''<p class="eyebrow">Evidence / immutable experiment record</p><h1>A negative result.<br>Fully accounted for.</h1><p class="lead">One hypothesis experiment. No competition upload. Source snapshots, raw failed checks, corrected checks and review findings are preserved together.</p>''' + metric_strip(card) + '''<section class="section" id="correction"><h2>The protocol error we found and fixed.</h2><div class="callout"><strong>Do not treat the first-pass holdout as promotion-qualified.</strong> The original pre-placement audit checked Spearman ranks but omitted positive-support overlap; it also continued despite an unassessable registry file. Review corrected both. The identical surface fails the pre-placement overlap gate. No new experiment, dot placement or TIFF followed the correction.</div><p>The original run card and rank scan remain in the evidence directory. The current card explicitly records the error and disqualifies the execution for promotion. The runner now applies both literal tests at both phases and stops before placement on any incomplete clearance. Shared geometry is reused without a private metric change.</p></section>
<section class="section"><div class="grid2"><article class="panel"><p class="kicker">Exploratory holdout diagnostics</p><h3>BGAC-1 loses to a simpler feature.</h3>''' + bars + '''<p class="small">HOLDOUT-DTI · gems57-pooled-hide-v2 · 56,454 withheld positives · 95% block-bootstrap intervals in the linked JSON. Same fixed budget and folds; not organizer scores. All feature AUC canaries fell between 0.4045 and 0.5727.</p><a href="evidence/holdout.json">Every arm, CI and fold →</a></article><article class="panel"><p class="kicker">Validation scope</p><h3>No phantom TIFF receipt.</h3><p>The in-memory surface is finite and in [0,1]. No BGAC-1 submission file exists, so there is no on-disk BGAC-1 submission validator pass and its raster SHA256 is null. Reference-grid metadata is identified as reference-only, not as a generated TIFF.</p><p>The restored catalogue has the same SHA256 as the mirrored label raster. This is hide-and-recover proxy validation, not evaluation on hidden new-fault truth.</p><a href="evidence/run_card.json">Authoritative JSON run card →</a></article></div></section>
<section class="section"><div class="callout"><strong>Concurrent parallel-session work is preserved separately.</strong> Another session merged a synthetic, already holdout-negative research TIFF while this run was underway. Its original files are in a learning-only archive, not active downloads. Its projection and nine-champion uniqueness claims are not endorsed. <a href="https://github.com/sassnarep3-star/GEMSDOESASS1/tree/main/archive/parallel-main-f620a70">Review archive and byte hashes ↗</a></div><h2>Download audit evidence, not a duplicate submission.</h2><div class="panel"><ul class="evidence-list">''' + ''.join(f'<li><a href="evidence/{f}">{label}</a><span>JSON ↗</span></li>' for f, label in [('run_card.json','Current run card'),('first_pass_run_card.json','Preserved first-pass card'),('corrected_surface_novelty.json','Corrected pre-placement stop'),('surface_novelty.json','Original full rank-only surface scan'),('dot_novelty.json','First-pass final-dot stop'),('nine_site_audit.json','Nine-site byte / duplicate / H33 mechanism audit'),('canaries.json','Per-feature leakage canaries'),('holdout.json','Exploratory holdout and paired confidence intervals'),('feature_cache.json','Feature cache hashes and layer tags'),('focus_inventory.json','Complete frozen nine-site TIFF inventory'),('PROVENANCE.json','Unmodified shared-tool provenance'),('release_checks.json','Frozen implementation hashes and verification checks')]) + '''</ul></div></section><section class="section" id="feed"><p class="eyebrow">Source freshness feed</p><h2>Current source heads. Frozen results.</h2>''' + feedhtml + '''</section><section class="section"><h2>The run card.</h2><pre>''' + e(json.dumps(card, indent=2)) + '</pre></section>'
    (OUT / 'evidence.html').write_text(page('Evidence and source feed', evidencebody, active='evidence'))
    (OUT / '.nojekyll').write_text('')
    evidence_out = OUT / 'evidence'
    evidence_out.mkdir(exist_ok=True)
    for path in (ROOT / 'evidence').glob('*.json'):
        shutil.copyfile(path, evidence_out / path.name)
    for source, name in [('registry/focus_inventory.json','focus_inventory.json'), ('vendor/PROVENANCE.json','PROVENANCE.json'), ('knowledge/sources.json','sources.json')]:
        shutil.copyfile(ROOT / source, evidence_out / name)
    print('Built landing page, executive summary, research, evidence and nine individual site summaries.')


if __name__ == '__main__':
    main()
